def valid_date(date):
    def validate_date_format(date):
        if len(date) != 10:
            return False
        if not date[0:2].isdigit() or not 1 <= int(date[0:2]) <= 12:
            return False
        if date[2] != '-':
            return False
        if not date[3:5].isdigit():
            return False
        month = int(date[0:2])
        day = int(date[3:5])
        if month in [1, 3, 5, 7, 8, 10, 12] and not 1 <= day <= 31:
            return False
        if month in [4, 6, 9, 11] and not 1 <= day <= 30:
            return False
        if month == 2 and not 1 <= day <= 29:
            return False
        if date[5] != '-':
            return False
        if not date[6:].isdigit() or len(date[6:]) != 4:
            return False
        return True

    def validate_date_range(date):
        month_days = {
            1: 31, 2: 29, 3: 31, 4: 30, 5: 31, 6: 30, 7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31
        }
        month = int(date[0:2])
        day = int(date[3:5])
        if day > month_days[month]:
            return False
        return True

    if not date:
        return False

    if not validate_date_format(date):
        return False

    if not validate_date_range(date):
        return False

    return True
